\label{parts.lem}If $\lambda>d$ and $\psi$ is a continuously differentiable
function for which $\psi$ and $N\psi$ are bounded, then 
\begin{align*}
c_{\lambda}\int_{\mathbb{B}^{d}}\psi(z)(1-|z|^{2})^{\lambda-d-1}dz  &
=c_{\lambda+1}\int_{\mathbb{B}^{d}}\left[  \left(  I+\frac{N}{\lambda}\right)
\psi\right]  (z)(1-|z|^{2})^{\lambda-d}~dz\\
&  =c_{\lambda+1}\int_{\mathbb{B}^{d}}\left[  \left(  I+\frac{\bar{N}} 
{\lambda}\right)  \psi\right]  (z)(1-|z|^{2})^{\lambda-d}~dz.
\end{align*}
Here $dz$ is the $2d$-dimensional Lebesgue measure on $\mathbb{B}^{d}.$

\label{shift1.prop}Suppose that $\lambda>d$ and $f$ and $g$ are holomorphic
functions on $\mathbb{B}^{d}$ for which $f,$ $g,$ $Nf,$ and $Ng$ are all
bounded. Then 
\begin{equation}
\left\langle f,g\right\rangle _{L^{2}(\mathbb{B}^{d},\mu_{\lambda} 
)}=\left\langle f,\left(  I+\frac{N}{\lambda}\right)  g\right\rangle
_{L^{2}(\mathbb{B}^{d},\mu_{\lambda+1})}=\left\langle \left(  I+\frac
{N}{\lambda}\right)  f,g\right\rangle _{L^{2}(\mathbb{B}^{d},\mu_{\lambda+1} 
)}. \label{shift1} 
\end{equation}

\label{shift2n.thm}Fix $\lambda>d$ and a non-negative integer $n.$ Then a
holomorphic function $f$ on $\mathbb{B}^{d}$ belongs to $\mathcal{H} 
L^{2}(\mathbb{B}^{d},\mu_{\lambda})$ if and only if $N^{l}f$ belongs to
$\mathcal{H}L^{2}(\mathbb{B}^{d},\mu_{\lambda+2n})$ for $0\leq l\leq n.$
Furthermore, 
\begin{equation}
\left\langle f,g\right\rangle _{\mathcal{H}L^{2}(\mathbb{B}^{d},\mu_{\lambda
})}=\left\langle Af,Bg\right\rangle _{\mathcal{H}L^{2}(\mathbb{B}^{d} 
,\mu_{\lambda+2n})} \label{shift2n} 
\end{equation}
for all $f,g\in\mathcal{H}L^{2}(\mathbb{B}^{d},\mu_{\lambda}),$ where 
\begin{align*}
A  &  =\left(  I+\frac{N}{\lambda+n}\right)  \left(  I+\frac{N}{\lambda
+n+1}\right)  \cdots\left(  I+\frac{N}{\lambda+2n-1}\right) \\
B  &  =\left(  I+\frac{N}{\lambda}\right)  \left(  I+\frac{N}{\lambda
+1}\right)  \cdots\left(  I+\frac{N}{\lambda+n-1}\right)  .
\end{align*}

If, say, $\lambda_{1}>d,$ then we have the following simple argument: 
\begin{align*}
\left\Vert fg\right\Vert _{\lambda_{1}+\lambda_{2}}^{2}  &  =c_{\lambda
_{1}+\lambda_{2}}\int_{\mathbb{B}^{d}}\left\vert f(z)\right\vert
^{2}\left\vert g(z)\right\vert ^{2}(1-\left\vert z\right\vert ^{2} 
)^{\lambda_{1}+\lambda_{2}}~d\tau(z)\\
&  \leq c_{\lambda_{1}+\lambda_{2}}\left\Vert g\right\Vert _{\lambda_{2}} 
^{2}\int_{\mathbb{B}^{d}}\left\vert f(z)\right\vert ^{2}(1-\left\vert
z\right\vert ^{2})^{-\lambda_{2}}(1-\left\vert z\right\vert ^{2})^{\lambda
_{1}+\lambda_{2}}~d\tau(z)\\
&  =\frac{c_{\lambda_{1}+\lambda_{2}}}{c_{\lambda_{1}}}\left\Vert f\right\Vert
_{\lambda_{1}}^{2}\left\Vert g\right\Vert _{\lambda_{2}}^{2}.
\end{align*}
Unfortunately, $c_{\lambda_{1}+\lambda_{2}}/c_{\lambda_{1}}$ tends to infinity
as $\lambda_{1}$ approaches $d$ from above, so we cannot expect this simple
inequality to hold for $\lambda_{1}<d.$

For any $\lambda_{1},\lambda_{2}>0,$ choose $n$ so that $\lambda_{1}+n>d$ and
$\lambda_{2}+n>d.$ Then $fg$ belongs to $H(\mathbb{B}^{d},\lambda_{1} 
+\lambda_{2})$ provided that $N^{n}(fg)$ belongs to $\mathcal{H} 
L^{2}(\mathbb{B}^{d},\lambda_{1}+\lambda_{2}+2n).$ But 
\begin{equation}
N^{n}(fg)=\sum_{k=0}^{n}\binom{n}{k}N^{k}f~N^{n-k}g. \label{kterm} 
\end{equation}
Using Theorem {{\rm\expandafter\@setref\csname r@bergmansobolev.thm\endcsname\@firstoftwo{bergmansobolev.thm}}}, it is easy to see that if $f$ belongs
to $H(\mathbb{B}^{d},\lambda_{1})$ then $N^{k}f$ belongs to $H(\mathbb{B} 
^{d},\lambda_{1}+2k)$. Thus, 
\[
\left\vert N^{k}f(z)\right\vert ^{2}\leq a_{k}(1-\left\vert z\right\vert
^{2})^{-(\lambda_{1}+2k)}.
\]


Now, for each term in ({{\rm\expandafter\@setref\csname r@kterm\endcsname\@firstoftwo{kterm}}}) with $k\leq n/2$, we then obtain the
following norm estimate: 
\begin{align}
&  c_{\lambda_{1}+\lambda_{2}+2n}\int_{\mathbb{B}^{d}}\left\vert
N^{k}f(z)N^{n-k}g(z)\right\vert ^{2}~(1-\left\vert z\right\vert ^{2} 
)^{\lambda_{1}+\lambda_{2}+2n}~d\tau(z)\nonumber\\
&  \leq c_{\lambda_{1}+\lambda_{2}+2n}a_{k}\int_{\mathbb{B}^{d}}\left\vert
N^{n-k}g(z)\right\vert ^{2}(1-\left\vert z\right\vert ^{2})^{\lambda
_{2}+2n-2k}~d\tau(z). \label{knorm} 
\end{align}
Since $k\leq n/2,$ we have $\lambda_{2}+2n-2k\geq\lambda_{2}+n>d.$ We are
assuming that $g$ is in $H(\mathbb{B}^{d},\lambda_{2}),$ so that $N^{n-k}g$ is
in $H(\mathbb{B}^{d},\lambda_{2}+2n-2k),$ which coincides with $\mathcal{H} 
L^{2}(\mathbb{B}^{d},\mu_{\lambda_{2}+2n-2k}).$ Thus, under our assumptions on
$f$ and $g,$ each term in ({{\rm\expandafter\@setref\csname r@kterm\endcsname\@firstoftwo{kterm}}}) with $k\leq n/2$ belongs to
$\mathcal{H}L^{2}(\mathbb{B}^{d},\lambda_{1}+\lambda_{2}+2n).$ A similar
argument with the roles of $f$ and $g$ reversed takes care of the terms with
$k\geq n/2.$

\label{basic.prop}For $\lambda>d$ and $\phi(z)$ bounded, the Toeplitz operator
$T_{\phi}$ on the space $\mathcal{H}L^{2}(\mathbb{B}^{d},d\mu_{\lambda}),$ which is
defined by $T_{\phi}f=P_{\lambda}(\phi f),$ has the following properties.

\begin{enumerate}
\@par\hangindent 2em $\|T_{\phi}\|\leq\sup_{z}|\phi(z)|$

\@par\hangindent 2em If $\phi(z)\geq0$ for all $z,$ then $T_{\phi}$ is a positive operator.
\end{enumerate}

Both of these properties fail when $\lambda<d.$ In fact, for $\lambda<d,$
there is no constant $C$ such that $\Vert T_{\phi}\Vert\leq C\sup_{z} 
|\phi(z)|$ for all polynomials $\phi.$

\label{sobolevtoep.thm}Assume $\lambda>d$ and fix a positive integer $n.$ Let
$\phi$ be a function that is $2n$ times continuously differentiable and for
which $\bar{N}^{k}N^{l}\phi$ is bounded for all $0\leq k,l\leq n.$ Then 
\[
\left\langle f,T_{\phi}g\right\rangle _{\mathcal{H}L^{2}(\mathbb{B}^{d} 
,\mu_{\lambda})}=c_{\lambda+2n}\int_{\mathbb{B}^{d}}C\left[  \left(
\overline{f(z)}\phi(z)g(z)\right)  \right]  \left(  1-|z|^{2}\right)
^{\lambda+2n}d\tau(z)
\]
for all $f,g\in\mathcal{H}L^{2}(\mathbb{B}^{d},\mu_{\lambda}),$ where $C$ is
the operator given by 
\begin{equation}
C=\left(  I+\frac{\bar{N}}{\lambda+2n-1}\right)  \cdots\left(  I+\frac{\bar
{N}}{\lambda+n}\right)  \left(  I+\frac{N}{\lambda+n-1}\right)  \cdots\left(
I+\frac{N}{\lambda}\right)  . \label{cop} 
\end{equation}
Thus, there exist constants $A_{jklm}$ (depending on $n$ and $\lambda$) such
that 
\begin{equation}
\left\langle f,T_{\phi}g\right\rangle _{\mathcal{H}L^{2}(\mathbb{B}^{d} 
,\mu_{\lambda})}=\sum_{j,k,l,m=1}^{n}A_{jklm}\left\langle N^{j}f,\left(
\bar{N}^{k}N^{l}\phi\right)  N^{m}g\right\rangle _{L^{2}(\mathbb{B}^{d} 
,\mu_{\lambda+2n})}. \label{cexpanded} 
\end{equation}

\label{sobolevtoep.def}Assume $0<\lambda\leq d$ and fix a positive integer $n$
such that $\lambda+2n>d.$ Let $\phi$ be a function that is $2n$ times
continuously differentiable and for which $\bar{N}^{k}N^{l}\phi$ is bounded
for all $0\leq k,l\leq n.$ Then we define the Toeplitz operator $T_{\phi}$ to
be the unique bounded operator on $H(\mathbb{B}^{d},\lambda)$ whose matrix
entries are given by 
\begin{equation}
\left\langle f,T_{\phi}g\right\rangle _{H(\mathbb{B}^{d},\lambda)} 
=c_{\lambda+2n}\int_{\mathbb{B}^{d}}C\left[  \left(  \overline{f(z)} 
\phi(z)g(z)\right)  \right]  \left(  1-|z|^{2}\right)  ^{\lambda+2n}dz,
\label{sobolevtoep.form} 
\end{equation}
where $C$ is given by ({{\rm\expandafter\@setref\csname r@cop\endcsname\@firstoftwo{cop}}}).

\label{hsl2.thm}Fix $\lambda>d/2.$ Then for each $\phi\in L^{2}(\mathbb{B} 
^{d},\tau)$, there is a unique Hilbert--Schmidt operator on $H(\mathbb{B} 
^{d},\lambda),$ denoted $T_{\phi},$ with the property that 
\begin{equation}
\left\langle f,T_{\phi}g\right\rangle _{\lambda}=c_{\lambda}\int
_{\mathbb{B}^{d}}\overline{f(z)}\phi(z)g(z)(1-|z|^{2})^{\lambda}~d\tau(z)
\label{hsmatrix2} 
\end{equation}
for all bounded holomorphic functions $f$ and $g$ in $H(\mathbb{B}^{d} 
,\lambda).$ The Hilbert--Schmidt norm of $T_{\phi}$ is given by 
\[
\left\Vert T_{\phi}\right\Vert _{HS}^{2}=\left\langle \phi,A_{\lambda} 
\phi\right\rangle _{L^{2}(\mathbb{B}^{d},\tau)}.
\]
